const ts = 1788269400.0;
const dt = new Date(ts * 1000);

console.log('=== Timestamp 1788269400.0 in UTC ===');
console.log('UTC:', dt.toISOString());
console.log();

// September 1, 2026 → Eastern Daylight Time (EDT) = UTC-4
const edtOffsetHours = -4;
const localHour = dt.getUTCHours() + edtOffsetHours;
const localMinute = dt.getUTCMinutes();
console.log('=== Converting to Eastern Time (EDT, UTC-4) ===');
console.log('In September, Eastern Time = EDT (UTC−4)');
console.log('Local time: ' + ((localHour % 12) || 12) + ':' + String(localMinute).padStart(2,'0') + (localHour >= 12 ? ' PM' : ' AM') + ' EDT');
console.log('24h format: ' + localHour + ':' + String(localMinute).padStart(2,'0'));
console.log();

const is630pmET = (localHour === 18 && localMinute === 30);
console.log('=== 6:30 PM ET Check ===');
console.log(is630pmET ? '✅ YES — matches 6:30 PM ET' : '❌ NO — does NOT match 6:30 PM ET');
console.log();

// What timestamp WOULD be 6:30 PM EDT on 2026-09-01?
const correctUTC = new Date(Date.UTC(2026, 8, 1, 22, 30, 0)); // 18:30 EDT = 22:30 UTC
const correctTs = correctUTC.getTime() / 1000;
console.log('=== Correct timestamp for 6:30 PM EDT on 2026-09-01 ===');
console.log('6:30 PM EDT = 22:30 UTC');
console.log('Correct POSIX timestamp:', correctTs);
console.log('Difference from given:', correctTs - ts, 'seconds (' + (correctTs - ts)/3600 + ' hours)');
"
